/*
 PLAN
 1) Composition: a graded backdrop plane (7x6 @ z=-2.5), a machined ribbon rail 7.0w x 0.35h at origin with hairlines, mono ticker figures floating +0.02z scrolling left, red tick marks between entries, edge-fade masks 0.6u at both ends.
 2) Light rig: rig-tech-clinical — key #f2f4f6 2.2 @ [1.6,3,2.6], fill #e6e9ee 1.5 @ [-2,2.4,2.2], rim #ffffff 1.0 @ [0,2,-3]; node-local, all targeted at the rail.
 3) Materials: rail = MeshStandardNodeMaterial albedo #111117 rough 0.6 metal 0.2; hairlines #23232b; ticks emissive #ff2a38 intensity 1.5; backdrop = TSL vertical gradient of spec stops (paper text via fontAtlas MSDF).
 4) Motion: fly-through primitive (time trigger) plus deterministic linear GSAP loop translating the duplicated strip left at 0.4 u/s, seamless wrap; no easing, no vertical motion.
 5) Focal element: the scrolling paper mono figures punctuated by the single red emissive ticks — the brightest read on the frame.
*/
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, float, positionWorld } from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  background: '#0b0b10',
  surface: '#111117',
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  hairline: '#23232b',
};

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, Object3D, Color } = THREE;

  const root = new Group();
  root.name = 'data-ticker-ribbon';

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  const track = (m) => { disposables.push(m); return m; };

  // ---------- stageBackdrop: graded stage, never flat void (color.gradient / color.background) ----------
  const bgMat = new MeshBasicNodeMaterial();
  {
    const cBg = vec3(0.0431, 0.0431, 0.0627); // #0b0b10
    const cSurf = vec3(0.0667, 0.0667, 0.0902); // #111117
    const v = uv().y;
    // vertical grade: background at extremes, slightly lifted surface tone mid-frame
    const lift = smoothstep(0.09, 0.5, v).mul(smoothstep(0.91, 0.5, v));
    bgMat.colorNode = mix(cBg, cSurf, lift.mul(0.85));
  }
  const backdrop = new Mesh(track(new PlaneGeometry(7, 6)), track(bgMat));
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- lightRig: rig-tech-clinical ----------
  const lightRig = new Group();
  const aimAt = (pos, tgt) => {
    const l = new DirectionalLight();
    l.position.set(pos[0], pos[1], pos[2]);
    const t = new Object3D();
    t.position.set(tgt[0], tgt[1], tgt[2]);
    lightRig.add(t);
    l.target = t;
    return l;
  };
  const key = aimAt([1.6, 3, 2.6], [0, 0.4, 0]);
  key.color = new Color('#f2f4f6'); key.intensity = 2.2;
  const fill = aimAt([-2, 2.4, 2.2], [0, 0.4, 0]);
  fill.color = new Color('#e6e9ee'); fill.intensity = 1.5;
  const rim = aimAt([0, 2, -3], [0, 0.5, 0]);
  rim.color = new Color('#ffffff'); rim.intensity = 1.0;
  lightRig.add(key, fill, rim);
  root.add(lightRig);

  // ---------- ribbonRail: 7.0 x 0.35 machined surface (color.surface / effects.spec) ----------
  const railMat = new MeshStandardNodeMaterial();
  railMat.color = new Color(COLORS.surface);
  railMat.roughness = 0.6;
  railMat.metalness = 0.2;
  const rail = new Mesh(track(new BoxGeometry(7.0, 0.35, 0.03)), track(railMat));
  rail.position.set(0, 0, 0);
  root.add(rail);

  // hairlines: top and bottom 0.006u, #23232b (color.ink used as inset shadow line below)
  const hairMat = new MeshStandardNodeMaterial();
  hairMat.color = new Color(COLORS.hairline);
  hairMat.roughness = 0.5;
  hairMat.metalness = 0.35;
  track(hairMat);
  const hairGeo = track(new BoxGeometry(7.0, 0.006, 0.032));
  const hairTop = new Mesh(hairGeo, hairMat);
  hairTop.position.set(0, 0.175, 0.001);
  const hairBot = new Mesh(hairGeo, hairMat);
  hairBot.position.set(0, -0.175, 0.001);
  root.add(hairTop, hairBot);

  // ink shadow strips grounding the rail against the stage (color.ink)
  const inkMat = new MeshBasicNodeMaterial();
  inkMat.colorNode = vec3(0.0863, 0.0863, 0.1137); // #16161d
  track(inkMat);
  const inkGeo = track(new PlaneGeometry(7.0, 0.05));
  const inkShadow = new Mesh(inkGeo, inkMat);
  inkShadow.position.set(0, -0.21, -0.005);
  root.add(inkShadow);

  // ---------- tickerStrip: mono figures + accent ticks, duplicated for seamless loop ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const GAP = 0.5; // 2x base unit each side of tick
  const TICK_W = 0.02, TICK_H = 0.14;
  const SPEED = 0.4;

  const tickMat = new MeshStandardNodeMaterial();
  tickMat.color = new Color(COLORS.accent);
  tickMat.emissive = new Color(COLORS.accent);
  tickMat.emissiveIntensity = 1.5;
  tickMat.roughness = 0.5;
  tickMat.metalness = 0.1;
  track(tickMat);
  const tickGeo = track(new BoxGeometry(TICK_W, TICK_H, 0.02));

  function buildStrip() {
    const strip = new Group();
    let cursor = 0;
    for (const item of items) {
      const label = ctx.fontAtlas.createText(String(item.text), {
        fontSize: item.typography?.fontSize ?? 13,
        color: COLORS.paper,
        align: 'left',
        letterSpacingPx: 0.06 * 13,
      });
      // measure text width via bounding box; fallback estimate
      let w = 0;
      const box = new THREE.Box3().setFromObject(label);
      if (isFinite(box.max.x) && isFinite(box.min.x)) w = box.max.x - box.min.x;
      if (!(w > 0)) w = String(item.text).length * 0.08;
      label.position.set(cursor, 0, 0.02); // float above the rail for crisp key-lit edge
      strip.add(label);
      cursor += w + GAP;
      const tick = new Mesh(tickGeo, tickMat);
      tick.position.set(cursor + TICK_W / 2, 0, 0.02);
      strip.add(tick);
      cursor += TICK_W + GAP;
    }
    return { strip, length: cursor };
  }

  const ribbonContent = new Group();
  const a = buildStrip();
  const b = buildStrip();
  b.strip.position.x = a.length;
  ribbonContent.add(a.strip, b.strip);
  ribbonContent.position.set(-3.5, -0.045, 0);
  root.add(ribbonContent);

  // ---------- edgeFadeMasks: 0.6u fade at both ends using spec stop ramp ----------
  const makeFadeMat = (flip) => {
    const m = new MeshBasicNodeMaterial();
    m.transparent = true;
    m.depthWrite = false;
    let x = uv().x;
    if (flip) x = float(1.0).sub(x);
    // ramp: #0b0b10 alpha 1.0 at 0 -> alpha 0 at 0.09 of full 7u frame => within 0.6u mask: full ramp
    const alpha = float(1.0).sub(smoothstep(0.0, 1.0, x));
    m.colorNode = vec4(0.0431, 0.0431, 0.0627, alpha);
    return track(m);
  };
  const fadeGeo = track(new PlaneGeometry(0.6, 0.45));
  const fadeL = new Mesh(fadeGeo, makeFadeMat(false));
  fadeL.position.set(-3.5 + 0.3, 0, 0.06);
  const fadeR = new Mesh(fadeGeo, makeFadeMat(true));
  fadeR.position.set(3.5 - 0.3, 0, 0.06);
  fadeR.renderOrder = fadeL.renderOrder = 10;
  root.add(fadeL, fadeR);

  // ---------- motion: constant-velocity seamless loop (linear, no easing) ----------
  const loopLen = a.length;
  const period = loopLen / SPEED;
  const scrollTl = gsap.timeline({ repeat: -1 });
  scrollTl.fromTo(
    ribbonContent.position,
    { x: -3.5 },
    { x: -3.5 - loopLen, duration: period, ease: 'none' }
  );
  timelines.push(scrollTl);

  // weighted-settle entrance for the whole ribbon (rise-in, power3.out)
  const enterTl = gsap.timeline();
  enterTl.from(root.position, { y: -0.4, duration: 0.7, ease: 'power3.out' });
  timelines.push(enterTl);

  // ---------- applyPrimitives: EVERY config primitive via ctx.primitives ----------
  for (const p of config.cinematicPrimitives ?? []) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      const h = ctx.primitives[p.name](ribbonContent, p.params ?? {});
      if (h) primitiveHandles.push(h);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primitiveHandles.forEach((h) => h.cleanup && h.cleanup());
    disposables.forEach((d) => d.dispose && d.dispose());
    root.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose?.();
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        mats.forEach((m) => m?.dispose?.());
      }
    });
  };

  return root;
}

