{"elements":[
{"id":"text.ticker-figure.0","where":"buildStrip","how":"MSDF text from textContent item 0"},
{"id":"text.ticker-figure.1","where":"buildStrip","how":"MSDF text from textContent item 1"},
{"id":"text.ticker-figure.2","where":"buildStrip","how":"MSDF text from textContent item 2"},
{"id":"text.ticker-figure.3","where":"buildStrip","how":"MSDF text from textContent item 3"},
{"id":"text.ticker-figure.4","where":"buildStrip","how":"MSDF text from textContent item 4"},
{"id":"text.ticker-figure.5","where":"buildStrip","how":"MSDF text from textContent item 5"},
{"id":"color.background","where":"stageBackdrop","how":"gradient base and fade mask color"},
{"id":"color.surface","where":"ribbonRail","how":"rail albedo #111117"},
{"id":"color.ink","where":"ribbonRail","how":"inkShadow grounding strip #16161d"},
{"id":"color.paper","where":"buildStrip","how":"ticker figure text color #e8ecf2"},
{"id":"color.accent","where":"buildStrip","how":"emissive red tick marks intensity 1.5"},
{"id":"color.gradient","where":"edgeFadeMasks","how":"stop ramp opaque-to-clear both ends"},
